(() => {
  'use strict';
  const canvas = document.getElementById('game'), ctx = canvas.getContext('2d');
  const $ = id => document.getElementById(id);
  const ui = {top:$('topbar'), health:$('health-panel'), objective:$('objective-panel'), footer:$('game-footer'), mobile:$('mobile-controls'), welcome:$('welcome-screen'), level:$('level-screen'), pause:$('pause-screen'), end:$('end-screen'), healthFill:$('health-fill'), healthText:$('health-text'), xpFill:$('xp-fill'), xpText:$('xp-text'), levelText:$('level'), timer:$('timer'), wave:$('wave'), kills:$('kills'), objectiveFill:$('objective-fill'), objectiveCopy:$('objective-copy'), toast:$('toast'), flash:$('damage-flash')};
  const TAU = Math.PI * 2, rand = (a,b) => a + Math.random()*(b-a), clamp = (v,a,b) => Math.max(a,Math.min(b,v));
  let W=innerWidth,H=innerHeight,DPR=1, last=0, state='title', time=0, spawnClock=0, hudClock=0, shake=0, toastClock=0;
  let player, enemies=[], orbs=[], bolts=[], particles=[], slashes=[], decor=[], keys={}, stick={x:0,y:0}, joystick=null;
  const RUN_LENGTH=360;
  const upgrades=[
    {id:'edge',icon:'⚔',name:'Keen Edge',desc:'Sword strikes deal 35% more damage.',tag:'OFFENSE',apply:p=>p.damage*=1.35},
    {id:'heart',icon:'✚',name:'Dragonheart',desc:'Restore 35 vitality and increase max vitality by 10.',tag:'VITALITY',apply:p=>{p.maxHp+=10;p.hp=Math.min(p.maxHp,p.hp+35)}},
    {id:'swift',icon:'➤',name:'Swiftblood',desc:'Move 12% faster and dash cooldown recovers sooner.',tag:'MOBILITY',apply:p=>{p.speed*=1.12;p.dashMax*=.86;p.dashCd=Math.min(p.dashCd,p.dashMax)}},
    {id:'ash',icon:'♨',name:'Ashwing’s Pact',desc:'The dragon fires 30% faster and burns for more.',tag:'FAMILIAR',apply:p=>{p.dragonRate*=.7;p.dragonDamage*=1.25}},
    {id:'reach',icon:'◉',name:'Wide Arc',desc:'Sword reach grows by 22%, striking more foes.',tag:'MASTERY',apply:p=>p.reach*=1.22},
    {id:'magnet',icon:'✧',name:'Soul Magnet',desc:'Draw ember orbs from much farther away.',tag:'UTILITY',apply:p=>p.magnet+=70},
    {id:'armor',icon:'⬟',name:'Scale Mail',desc:'Reduce incoming damage by 1 and gain 18 vitality.',tag:'DEFENSE',apply:p=>{p.armor++;p.maxHp+=18;p.hp=Math.min(p.maxHp,p.hp+18)}},
    {id:'cool',icon:'⟳',name:'Battle Rhythm',desc:'Sword strikes recover 20% faster.',tag:'MASTERY',apply:p=>p.attackRate*=.8}
  ];
  function resize(){W=innerWidth;H=innerHeight;DPR=Math.min(devicePixelRatio||1,2);canvas.width=Math.floor(W*DPR);canvas.height=Math.floor(H*DPR);canvas.style.width=W+'px';canvas.style.height=H+'px';ctx.setTransform(DPR,0,0,DPR,0,0)}
  addEventListener('resize',resize); resize();
  function newPlayer(){return {x:0,y:0,vx:0,vy:0,r:15,hp:100,maxHp:100,speed:210,damage:24,reach:92,attackRate:1.04,attackCd:.3,dragonRate:1.2,dragonCd:.3,dragonDamage:19,armor:0,dashMax:2.7,dashCd:0,dashTime:0,dashDir:{x:1,y:0},invuln:0,level:1,xp:0,nextXp:12,kills:0,walk:0,face:1,magnet:125,orbHeal:0}}
  function begin(){player=newPlayer();enemies=[];orbs=[];bolts=[];particles=[];slashes=[];time=0;spawnClock=0;hudClock=0;shake=0;decor=[];for(let i=0;i<72;i++){const a=i*2.399,b=rand(140,1800);decor.push({x:Math.cos(a)*b,y:Math.sin(a)*b,type:Math.random()<.54?'rock':'ruin',s:rand(.6,1.5),rot:rand(0,TAU)})}state='play';hide(ui.welcome);hide(ui.end);hide(ui.pause);hide(ui.level);show(ui.top);show(ui.health);show(ui.objective);show(ui.footer);ui.mobile.hidden=false;updateHud(true);toast('THE HUNT BEGINS',1.8)}
  function hide(el){el.hidden=true} function show(el){el.hidden=false}
  function showToast(s,d=1.5){ui.toast.textContent=s;ui.toast.classList.add('show');toastClock=d}
  $('start-button').addEventListener('click',begin);$('restart-button').addEventListener('click',begin);$('pause-button').addEventListener('click',togglePause);$('resume-button').addEventListener('click',togglePause);
  addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' ','Space'].includes(e.key))e.preventDefault();keys[e.key.toLowerCase()]=true;if((e.key==='Escape'||e.key.toLowerCase()==='p')&&state==='play')togglePause();else if((e.key==='Escape'||e.key.toLowerCase()==='p')&&state==='pause')togglePause();if((e.key===' '||e.code==='Space')&&state==='play')dash()});
  addEventListener('keyup',e=>{keys[e.key.toLowerCase()]=false});
  function togglePause(){if(state==='play'){state='pause';show(ui.pause)}else if(state==='pause'){state='play';hide(ui.pause);last=performance.now()}}
  $('dash-button').addEventListener('pointerdown',e=>{e.preventDefault();dash()});
  $('joystick').addEventListener('pointerdown',e=>{e.preventDefault();joystick=e.currentTarget;joystick.setPointerCapture(e.pointerId);moveStick(e)});
  $('joystick').addEventListener('pointermove',e=>{if(joystick)moveStick(e)});
  $('joystick').addEventListener('pointerup',e=>{joystick=null;stick.x=stick.y=0;$('joystick-knob').style.transform='translate(0,0)'});
  $('joystick').addEventListener('pointercancel',()=>{joystick=null;stick.x=stick.y=0;$('joystick-knob').style.transform='translate(0,0)'});
  function moveStick(e){const r=$('joystick').getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),m=Math.hypot(dx,dy),max=31,n=Math.min(max,m);stick.x=dx/(m||1)*(n/max);stick.y=dy/(m||1)*(n/max);$('joystick-knob').style.transform=`translate(${stick.x*n}px,${stick.y*n}px)`}
  function dash(){if(state!=='play'||player.dashCd>0)return;let x=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0)+stick.x,y=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0)+stick.y;if(Math.hypot(x,y)<.2){x=player.face;y=0}let m=Math.hypot(x,y);player.dashDir={x:x/m,y:y/m};player.dashTime=.22;player.dashCd=player.dashMax;player.invuln=Math.max(player.invuln,.34);for(let i=0;i<12;i++)particles.push({x:player.x-rand(0,18),y:player.y-rand(0,18),vx:rand(-90,90),vy:rand(-90,90),life:rand(.25,.55),max:.55,color:'#f0b75e',size:rand(2,5)})}
  function chooseUpgrade(){if(state!=='play')return;state='level';const box=$('upgrade-options');box.innerHTML='';let picks=[...upgrades].sort(()=>Math.random()-.5).slice(0,3);for(const u of picks){const b=document.createElement('button');b.className='upgrade-option';b.innerHTML=`<span class="upgrade-tag">${u.tag}</span><div class="upgrade-icon">${u.icon}</div><h3>${u.name}</h3><p>${u.desc}</p>`;b.addEventListener('click',()=>{u.apply(player);hide(ui.level);state='play';last=performance.now();showToast(`${u.name.toUpperCase()} ACQUIRED`)});box.appendChild(b)}show(ui.level)}
  function gainXp(n){player.xp+=n;while(player.xp>=player.nextXp){player.xp-=player.nextXp;player.level++;player.nextXp=Math.floor(player.nextXp*1.3+4);player.hp=Math.min(player.maxHp,player.hp+12);chooseUpgrade();break}}
  function spawnEnemy(){const ang=rand(0,TAU),dist=Math.max(W,H)*.65+rand(40,220),x=player.x+Math.cos(ang)*dist,y=player.y+Math.sin(ang)*dist,elapsed=time;let type='wraith';if(elapsed>25&&Math.random()<.25)type='brute';if(elapsed>70&&Math.random()<.28)type='stalker';if(elapsed>125&&Math.random()<.12)type='elite';let scale=1+Math.min(elapsed/240,.65),d={wraith:[34,72,14,1],brute:[96,40,22,1.4],stalker:[58,95,12,1],elite:[190,58,25,1.5]}[type];enemies.push({x,y,type,r:d[2],hp:d[0]*scale,maxHp:d[0]*scale,speed:d[1]*(1+Math.min(elapsed/500,.22)),damage:d[3],hit:0,attack:rand(.2,1.2),phase:rand(0,TAU),xp:type==='elite'?4:type==='brute'?2:1})}

function update(dt){if(state!=='play')return;time+=dt;spawnClock+=dt;hudClock+=dt;player.attackCd-=dt;player.dragonCd-=dt;player.dashCd=Math.max(0,player.dashCd-dt);player.dashTime=Math.max(0,player.dashTime-dt);player.invuln=Math.max(0,player.invuln-dt);player.walk+=dt*9;
  if(spawnClock>.62){spawnClock-=.62;let count=1+(time>45&&Math.random()<.35?1:0)+(time>120&&Math.random()<.3?1:0);for(let i=0;i<count;i++)spawnEnemy()}
  let ix=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0)+stick.x,iy=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0)+stick.y,im=Math.hypot(ix,iy);if(im>1){ix/=im;iy/=im}if(ix)player.face=Math.sign(ix);
  if(player.dashTime>0){player.x+=player.dashDir.x*player.speed*3.35*dt;player.y+=player.dashDir.y*player.speed*3.35*dt}else{player.x+=ix*player.speed*dt;player.y+=iy*player.speed*dt}
  if(player.attackCd<=0&&enemies.length){let target=null,best=player.reach*player.reach;for(const e of enemies){let d=(e.x-player.x)**2+(e.y-player.y)**2;if(d<best){best=d;target=e}}if(target){player.attackCd=player.attackRate;const angle=Math.atan2(target.y-player.y,target.x-player.x);slashes.push({x:player.x,y:player.y,a:angle,life:.27,max:.27,reach:player.reach});for(const e of enemies){let dx=e.x-player.x,dy=e.y-player.y,d=Math.hypot(dx,dy),diff=Math.atan2(dy,dx)-angle;while(diff>Math.PI)diff-=TAU;while(diff< -Math.PI)diff+=TAU;if(d<player.reach+e.r&&Math.abs(diff)<.85){damageEnemy(e,player.damage);e.x+=Math.cos(angle)*14;e.y+=Math.sin(angle)*14}}}}
  if(player.dragonCd<=0){player.dragonCd=player.dragonRate;let target=null,best=480*480;for(const e of enemies){let d=(e.x-player.x)**2+(e.y-player.y)**2;if(d<best){best=d;target=e}}if(target){let dx=target.x-player.x,dy=target.y-player.y,m=Math.hypot(dx,dy);bolts.push({x:player.x+Math.cos(time*2)*22,y:player.y-28+Math.sin(time*2)*12,vx:dx/m*390,vy:dy/m*390,life:1.55,damage:player.dragonDamage});for(let i=0;i<4;i++)particles.push({x:player.x+rand(-9,9),y:player.y-35,vx:rand(-15,15),vy:rand(-50,-20),life:.28,max:.28,color:'#f2a94f',size:rand(2,4)})}}
  for(const e of enemies){e.phase+=dt*4;e.hit=Math.max(0,e.hit-dt);let dx=player.x-e.x,dy=player.y-e.y,d=Math.hypot(dx,dy)||1;if(e.type==='stalker'){e.attack-=dt;if(d<290&&e.attack<=0){e.attack=2.2;bolts.push({x:e.x,y:e.y,vx:dx/d*155,vy:dy/d*155,life:2.1,damage:7,enemy:true})}if(d>220){e.x+=dx/d*e.speed*dt;e.y+=dy/d*e.speed*dt}}else{e.x+=dx/d*e.speed*dt;e.y+=dy/d*e.speed*dt}if(d<e.r+player.r+1&&player.invuln<=0&&e.attack<=0){takeDamage(e.damage);e.attack=e.type==='brute'?1.25:.85}}
  for(const b of bolts){b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt;if(!b.enemy){for(const e of enemies){if((e.x-b.x)**2+(e.y-b.y)**2<(e.r+9)**2){damageEnemy(e,b.damage);b.life=0;for(let i=0;i<5;i++)particles.push({x:b.x,y:b.y,vx:rand(-75,75),vy:rand(-75,75),life:.25,max:.25,color:'#ffb34e',size:rand(2,4)});break}}}else if((player.x-b.x)**2+(player.y-b.y)**2<(player.r+8)**2&&player.invuln<=0){takeDamage(b.damage);b.life=0}}
  bolts=bolts.filter(b=>b.life>0);for(const o of orbs){let dx=player.x-o.x,dy=player.y-o.y,d=Math.hypot(dx,dy);if(d<player.magnet){let pull=clamp((player.magnet-d)/player.magnet,0,1);o.vx+=dx/(d||1)*(130+pull*700)*dt;o.vy+=dy/(d||1)*(130+pull*700)*dt}o.x+=o.vx*dt;o.y+=o.vy*dt;o.vx*=Math.pow(.08,dt);o.vy*=Math.pow(.08,dt);if(d<player.r+o.r+5){o.dead=true;gainXp(o.value)}}orbs=orbs.filter(o=>!o.dead);
  for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt;p.vx*=Math.pow(.2,dt);p.vy*=Math.pow(.2,dt)}particles=particles.filter(p=>p.life>0);for(const s of slashes)s.life-=dt;slashes=slashes.filter(s=>s.life>0);
  enemies=enemies.filter(e=>{if(e.hp<=0){player.kills++;let drops=e.xp;for(let n=0;n<drops;n++){orbs.push({x:e.x+rand(-9,9),y:e.y+rand(-8,8),vx:rand(-25,25),vy:rand(-25,25),r:5,value:1});}for(let i=0;i<7;i++)particles.push({x:e.x,y:e.y,vx:rand(-100,100),vy:rand(-100,100),life:rand(.25,.55),max:.55,color:e.type==='elite'?'#ff8b57':'#9bc7a3',size:rand(2,5)});if(player.kills%10===0)showToast(`${player.kills} SOULS CLAIMED`);return false}return true});
  if(time>=RUN_LENGTH){finish(true);return}if(player.hp<=0){finish(false);return}if(toastClock>0){toastClock-=dt;if(toastClock<=0)ui.toast.classList.remove('show')}if(shake>0)shake=Math.max(0,shake-dt*18);if(hudClock>.12){hudClock=0;updateHud()}
}
function damageEnemy(e,n){e.hp-=n;e.hit=.12}
function takeDamage(n){player.hp=Math.max(0,player.hp-Math.max(1,n-player.armor));player.invuln=.65;shake=7;ui.flash.classList.add('hit');setTimeout(()=>ui.flash.classList.remove('hit'),140);for(let i=0;i<8;i++)particles.push({x:player.x,y:player.y,vx:rand(-110,110),vy:rand(-100,100),life:.35,max:.35,color:'#df6652',size:rand(2,5)})}
function updateHud(force){const p=player;if(!p)return;ui.healthFill.style.width=(100*p.hp/p.maxHp)+'%';ui.healthText.textContent=`${Math.ceil(p.hp)} / ${p.maxHp}`;ui.xpFill.style.width=(100*p.xp/p.nextXp)+'%';ui.xpText.textContent=`${p.xp} / ${p.nextXp}`;ui.levelText.textContent=String(p.level).padStart(2,'0');ui.timer.textContent=fmt(time);ui.wave.textContent=String(Math.floor(time/30)+1).padStart(2,'0');ui.kills.textContent=p.kills;ui.objectiveFill.style.width=(100*time/RUN_LENGTH)+'%';ui.objectiveCopy.textContent=time>=RUN_LENGTH-60?`Final stand · ${fmt(RUN_LENGTH-time)}`:`First light · ${fmt(RUN_LENGTH-time)}`}
function fmt(t){t=Math.max(0,Math.floor(t));return String(Math.floor(t/60)).padStart(2,'0')+':'+String(t%60).padStart(2,'0')}
function finish(win){state='end';hide(ui.level);hide(ui.pause);ui.mobile.hidden=true;ui.end.hidden=false;$('end-kicker').textContent=win?'THE DAWN RETURNS':'A LEGEND FALLS';$('end-title').innerHTML=win?'The fire <em>endures</em>':'The fire <em>fades</em>';$('end-copy').textContent=win?'You held the line. The kingdom lives to see morning.':'The frontier remembers your name.';$('end-time').textContent=fmt(time);$('end-kills').textContent=player.kills;$('end-level').textContent=player.level}

  function camera(){return {x:player?player.x:0,y:player?player.y:0}}
  function draw(){ctx.setTransform(DPR,0,0,DPR,0,0);ctx.clearRect(0,0,W,H);const cam=camera(),cx=W/2,cy=H/2,offx=(Math.random()-.5)*shake,offy=(Math.random()-.5)*shake;
    const bg=ctx.createRadialGradient(cx,cy,30,cx,cy,Math.max(W,H)*.8);bg.addColorStop(0,'#2b302b');bg.addColorStop(.55,'#252b28');bg.addColorStop(1,'#1b2020');ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
    ctx.save();ctx.translate(cx-cam.x+offx,cy-cam.y+offy);
    const grid=104;ctx.strokeStyle='rgba(195,177,131,.055)';ctx.lineWidth=1;let gx=Math.floor((cam.x-W/2)/grid)*grid,gy=Math.floor((cam.y-H/2)/grid)*grid;ctx.beginPath();for(let x=gx;x<cam.x+W/2+grid;x+=grid){ctx.moveTo(x,cam.y-H/2);ctx.lineTo(x,cam.y+H/2)}for(let y=gy;y<cam.y+H/2+grid;y+=grid){ctx.moveTo(cam.x-W/2,y);ctx.lineTo(cam.x+W/2,y)}ctx.stroke();
    const visibleDecor=decor.filter(d=>Math.abs(d.x-cam.x)<W*.75&&Math.abs(d.y-cam.y)<H*.75);for(const d of visibleDecor)drawDecor(d);
    for(const o of orbs)drawOrb(o);for(const e of enemies)drawEnemy(e);for(const b of bolts)drawBolt(b);for(const s of slashes)drawSlash(s);if(player)drawPlayer();for(const p of particles)drawParticle(p);ctx.restore();
    if(state==='title'){drawAtmosphere()}requestAnimationFrame(frame)}
  function drawAtmosphere(){const v=ctx.createRadialGradient(W*.69,H*.48,20,W*.69,H*.48,Math.max(W,H)*.54);v.addColorStop(0,'rgba(226,149,67,.045)');v.addColorStop(1,'rgba(0,0,0,0)');ctx.fillStyle=v;ctx.fillRect(0,0,W,H)}
  function drawDecor(d){ctx.save();ctx.translate(d.x,d.y);ctx.rotate(d.rot);ctx.scale(d.s,d.s);if(d.type==='rock'){ctx.fillStyle='#101615';ctx.beginPath();ctx.ellipse(3,5,17,11,0,0,TAU);ctx.fill();ctx.fillStyle='#444943';ctx.beginPath();ctx.moveTo(-14,4);ctx.lineTo(-8,-9);ctx.lineTo(3,-14);ctx.lineTo(13,-6);ctx.lineTo(15,4);ctx.lineTo(2,10);ctx.closePath();ctx.fill();ctx.strokeStyle='#69695c';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(-8,-7);ctx.lineTo(0,-3);ctx.lineTo(4,4);ctx.stroke();ctx.fillStyle='#856747';ctx.beginPath();ctx.arc(-20,11,2,0,TAU);ctx.arc(20,10,1.5,0,TAU);ctx.fill()}else{ctx.fillStyle='#111615';ctx.fillRect(-19,-14,38,28);ctx.fillStyle='#4a4b41';ctx.fillRect(-17,-18,34,8);ctx.fillStyle='#252b28';ctx.fillRect(-10,-5,20,19);ctx.fillStyle='#6b6759';ctx.fillRect(-18,-16,3,7);ctx.fillRect(14,-16,3,7);ctx.strokeStyle='#77705d';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-8,-8);ctx.lineTo(1,-2);ctx.lineTo(-2,8);ctx.stroke()}ctx.restore()}
  function drawOrb(o){let pulse=1+Math.sin(performance.now()/140+o.x)*.18;ctx.save();ctx.translate(o.x,o.y);ctx.shadowBlur=15;ctx.shadowColor='#9ce1a2';ctx.fillStyle='#b8e3a9';ctx.beginPath();ctx.arc(0,0,o.r*pulse,0,TAU);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#eff0c2';ctx.beginPath();ctx.arc(-1,-1,1.7,0,TAU);ctx.fill();ctx.restore()}
  function drawEnemy(e){ctx.save();ctx.translate(e.x,e.y+Math.sin(e.phase)*2);const hit=e.hit>0;ctx.shadowBlur=hit?18:10;ctx.shadowColor=e.type==='elite'?'#ff7850':'#b55749';let col=e.type==='brute'?'#606452':e.type==='stalker'?'#77785c':e.type==='elite'?'#a34f3e':'#656a59';ctx.fillStyle=hit?'#f4a185':col;ctx.beginPath();if(e.type==='brute'){ctx.ellipse(0,0,e.r*1.25,e.r*.92,0,0,TAU);ctx.moveTo(-e.r,-4);ctx.lineTo(-e.r-9,-14);ctx.lineTo(-e.r+2,-9);ctx.moveTo(e.r,-4);ctx.lineTo(e.r+9,-14);ctx.lineTo(e.r-2,-9)}else if(e.type==='elite'){ctx.moveTo(0,-e.r*1.35);ctx.lineTo(e.r*.8,-e.r*.5);ctx.lineTo(e.r*.74,e.r*.65);ctx.lineTo(0,e.r);ctx.lineTo(-e.r*.74,e.r*.65);ctx.lineTo(-e.r*.8,-e.r*.5);ctx.closePath()}else{ctx.ellipse(0,1,e.r*.86,e.r*1.15,0,0,TAU);ctx.moveTo(-e.r*.45,-e.r*.7);ctx.lineTo(-e.r*.8,-e.r*1.5);ctx.lineTo(-e.r*.15,-e.r*.95);ctx.moveTo(e.r*.45,-e.r*.7);ctx.lineTo(e.r*.8,-e.r*1.5);ctx.lineTo(e.r*.15,-e.r*.95)}ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#cf7256';ctx.beginPath();ctx.arc(-e.r*.3,-2,2,0,TAU);ctx.arc(e.r*.3,-2,2,0,TAU);ctx.fill();if(e.hp<e.maxHp){ctx.fillStyle='#1a1b18';ctx.fillRect(-e.r, -e.r-9,e.r*2,3);ctx.fillStyle='#c97153';ctx.fillRect(-e.r,-e.r-9,e.r*2*e.hp/e.maxHp,3)}ctx.restore()}
  function drawBolt(b){ctx.save();ctx.translate(b.x,b.y);ctx.rotate(Math.atan2(b.vy,b.vx));ctx.shadowBlur=16;ctx.shadowColor=b.enemy?'#db7864':'#f1a94f';ctx.fillStyle=b.enemy?'#e78767':'#ffb954';ctx.beginPath();ctx.ellipse(0,0,b.enemy?9:12,b.enemy?4:5,0,0,TAU);ctx.fill();ctx.fillStyle='#fff0bb';ctx.beginPath();ctx.arc(2,0,2,0,TAU);ctx.fill();ctx.restore()}
  function drawSlash(s){const alpha=s.life/s.max;ctx.save();ctx.translate(s.x,s.y);ctx.rotate(s.a);ctx.globalAlpha=alpha*.85;ctx.strokeStyle='#f6d08a';ctx.lineWidth=4;ctx.shadowBlur=16;ctx.shadowColor='#f4ae59';ctx.beginPath();ctx.arc(0,0,s.reach*.68,-.78,.78);ctx.stroke();ctx.strokeStyle='#fff0cf';ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(0,0,s.reach*.72,-.7,.7);ctx.stroke();ctx.restore()}
  function drawPlayer(){let p=player;ctx.save();ctx.translate(p.x,p.y);if(p.invuln>0&&Math.floor(performance.now()/65)%2)ctx.globalAlpha=.5;let bob=p.dashTime>0?0:Math.sin(p.walk)*1.5;ctx.translate(0,bob);ctx.shadowBlur=17;ctx.shadowColor='rgba(0,0,0,.7)';ctx.fillStyle='#111514';ctx.beginPath();ctx.ellipse(0,12,17,8,0,0,TAU);ctx.fill();ctx.shadowBlur=0;
    // cloak and legs
