function fmt(n){n=Math.max(0,Math.floor(n));return String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0')}function hud(){$('health-fill').style.width=100*p.hp/p.max+'%';$('health-text').textContent=`${Math.ceil(p.hp)} / ${p.max}`;$('xp-fill').style.width=100*p.xp/p.next+'%';$('xp-text').textContent=`${p.xp} / ${p.next}`;$('level').textContent=String(p.level).padStart(2,'0');$('timer').textContent=fmt(t);$('wave').textContent=String(Math.floor(t/30)+1).padStart(2,'0');$('kills').textContent=p.kills;$('objective-fill').style.width=100*t/RUN+'%';$('objective-copy').textContent=t>RUN-60?'Final stand · '+fmt(RUN-t):'First light · '+fmt(RUN-t)}function finish(win){state='end';hide(ui.level);hide(ui.pause);ui.mobile.hidden=true;show(ui.end);$('end-kicker').textContent=win?'THE DAWN RETURNS':'A LEGEND FALLS';$('end-title').innerHTML=win?'The fire <em>endures</em>':'The fire <em>fades</em>';$('end-copy').textContent=win?'You held the line. The kingdom lives to see morning.':'The frontier remembers your name.';$('end-time').textContent=fmt(t);$('end-kills').textContent=p.kills;$('end-level').textContent=p.level}
function drawDecor(d){ctx.save();ctx.translate(d.x,d.y);ctx.rotate(d.rot);ctx.scale(d.s,d.s);if(!d.type){ctx.fillStyle='#101615';ctx.beginPath();ctx.ellipse(3,5,17,11,0,0,TAU);ctx.fill();ctx.fillStyle='#444943';ctx.beginPath();ctx.moveTo(-14,4);ctx.lineTo(-8,-9);ctx.lineTo(3,-14);ctx.lineTo(13,-6);ctx.lineTo(15,4);ctx.lineTo(2,10);ctx.closePath();ctx.fill();ctx.strokeStyle='#69695c';ctx.beginPath();ctx.moveTo(-8,-7);ctx.lineTo(0,-3);ctx.lineTo(4,4);ctx.stroke()}else{ctx.fillStyle='#111615';ctx.fillRect(-19,-14,38,28);ctx.fillStyle='#4a4b41';ctx.fillRect(-17,-18,34,8);ctx.fillStyle='#252b28';ctx.fillRect(-10,-5,20,19);ctx.fillStyle='#6b6759';ctx.fillRect(-18,-16,3,7);ctx.fillRect(14,-16,3,7)}ctx.restore()}
