function formatTime(seconds){let s=Math.floor(seconds);return String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0')}
function hud(){ $('timer').textContent=formatTime(t);$('wave').textContent=String(Math.floor(t/60)+1).padStart(2,'0');$('kills').textContent=p.kills;$('health-text').textContent=Math.ceil(p.hp)+' / '+p.max;$('health-fill').style.width=clamp(p.hp/p.max*100,0,100)+'%';$('level').textContent=String(p.level).padStart(2,'0');$('xp-text').textContent=p.xp+' / '+p.next;$('xp-fill').style.width=clamp(p.xp/p.next*100,0,100)+'%';$('objective-copy').textContent=t>=RUN?'First light · dawn':`First light · ${formatTime(RUN-t)}`;$('objective-fill').style.width=clamp(t/RUN*100,0,100)+'%'}
function finish(won){state='end';hide(ui.pause);hide(ui.level);show(ui.end);$('end-kicker').textContent=won?'THE FIRST LIGHT':'A LEGEND FALLS';$('end-title').innerHTML=won?'The dawn <em>remembers</em>':'The fire <em>fades</em>';$('end-copy').textContent=won?'You held the line until morning. The kingdom will sing of you.':'The frontier remembers your name. Rise again, dragon knight.';$('end-time').textContent=formatTime(t);$('end-kills').textContent=p.kills;$('end-level').textContent=p.level}

function drawGround(){let g=ctx.createRadialGradient(W*.5,H*.42,20,W*.5,H*.5,Math.max(W,H)*.8);g.addColorStop(0,'#303a37');g.addColorStop(.58,'#25302e');g.addColorStop(1,'#192222');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);let ox=((W/2-p.x)%96+96)%96,oy=((H/2-p.y)%96+96)%96;ctx.save();ctx.strokeStyle='rgba(195,184,145,.045)';ctx.lineWidth=1;ctx.beginPath();for(let x=ox-96;x<W+96;x+=96){ctx.moveTo(x,0);ctx.lineTo(x,H)}for(let y=oy-96;y<H+96;y+=96){ctx.moveTo(0,y);ctx.lineTo(W,y)}ctx.stroke();ctx.restore();for(let d of decor){let x=W/2+d.x-p.x,y=H/2+d.y-p.y;if(x < -50||x>W+50||y < -50||y>H+50)continue;ctx.save();ctx.translate(x,y);ctx.rotate(d.rot);ctx.globalAlpha=.35*d.s;if(d.type===0){ctx.fillStyle='#80917c';ctx.beginPath();ctx.ellipse(0,0,3*d.s,7*d.s,0,0,TAU);ctx.fill();ctx.fillStyle='#d5bc83';ctx.beginPath();ctx.arc(2*d.s,-2*d.s,1.3*d.s,0,TAU);ctx.fill()}else{ctx.fillStyle='#11191a';ctx.beginPath();ctx.ellipse(0,2*d.s,5*d.s,3*d.s,0,0,TAU);ctx.fill();ctx.strokeStyle='#7b8272';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(-2,1);ctx.lineTo(1,-3);ctx.lineTo(3,1);ctx.stroke()}ctx.restore()}}
function world(x,y){return{x:W/2+x-p.x,y:H/2+y-p.y}}
function drawFoe(e){let q=world(e.x,e.y),pulse=.5+Math.sin(e.phase)*.15;ctx.save();ctx.translate(q.x,q.y);ctx.globalAlpha=.24;ctx.fillStyle='#0a1112';ctx.beginPath();ctx.ellipse(0,e.r*.64,e.r*1.12,e.r*.48,0,0,TAU);ctx.fill();ctx.globalAlpha=1;let col=e.type==='brute'?'#725e4c':e.type==='stalker'?'#b47a54':e.type==='elite'?'#c45b42':'#8caa94';if(e.hit>0)col='#f4ddba';ctx.shadowColor=e.type==='elite'?'#ec6848':'#8fc2a0';ctx.shadowBlur=e.type==='elite'?17:8;ctx.fillStyle=col;ctx.beginPath();ctx.arc(0,0,e.r*(e.type==='elite'?1.02:1),0,TAU);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='rgba(20,25,24,.75)';ctx.beginPath();ctx.arc(-e.r*.28,-e.r*.12,Math.max(2,e.r*.11),0,TAU);ctx.arc(e.r*.28,-e.r*.12,Math.max(2,e.r*.11),0,TAU);ctx.fill();ctx.strokeStyle='rgba(20,25,24,.7)';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,e.r*.03,e.r*.43,.25,Math.PI-.25);ctx.stroke();if(e.type==='elite'){ctx.strokeStyle='#efb45e';ctx.lineWidth=3;ctx.beginPath();ctx.arc(0,0,e.r+5+pulse*3,0,TAU);ctx.stroke()}if(e.hp<e.max){ctx.fillStyle='rgba(10,12,12,.7)';ctx.fillRect(-e.r,-e.r-11,e.r*2,3);ctx.fillStyle='#d96c56';ctx.fillRect(-e.r,-e.r-11,e.r*2*clamp(e.hp/e.max,0,1),3)}ctx.restore()}
function drawKnight(){let x=W/2,y=H/2;ctx.save();ctx.translate(x,y);ctx.fillStyle='rgba(5,9,10,.5)';ctx.beginPath();ctx.ellipse(0,12,20,10,0,0,TAU);ctx.fill();if(p.invuln>0&&Math.floor(t*22)%2===0)ctx.globalAlpha=.48;let bob=Math.sin(p.walk)*1.5;ctx.translate(0,bob);ctx.fillStyle='#7c342d';ctx.beginPath();ctx.moveTo(-9,2);ctx.lineTo(-15,19);ctx.lineTo(0,14);ctx.lineTo(12,19);ctx.lineTo(8,1);ctx.closePath();ctx.fill();ctx.fillStyle='#c2b9a2';ctx.beginPath();ctx.ellipse(0,1,10,12,0,0,TAU);ctx.fill();ctx.fillStyle='#e2d4b8';ctx.beginPath();ctx.arc(0,-10,8,0,TAU);ctx.fill();ctx.fillStyle='#4b5553';ctx.beginPath();ctx.arc(0,-12,9,Math.PI,TAU);ctx.lineTo(8,-9);ctx.lineTo(-8,-9);ctx.closePath();ctx.fill();ctx.fillStyle='#e8b458';ctx.fillRect(p.face*3-1,-11,3,2);ctx.strokeStyle='#ded1b1';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(p.face*8,0);ctx.lineTo(p.face*17,-8);ctx.stroke();ctx.strokeStyle='#b98143';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(p.face*11,-2);ctx.lineTo(p.face*6,3);ctx.stroke();ctx.restore();let dx=28+Math.cos(t*2.7)*17,dy=-42+Math.sin(t*2.7)*11;ctx.save();ctx.translate(x+dx,y+dy);ctx.shadowColor='#f49a44';ctx.shadowBlur=15;ctx.fillStyle='#e9a14d';ctx.beginPath();ctx.ellipse(0,0,9,6,Math.sin(t*3)*.3,0,TAU);ctx.fill();ctx.fillStyle='#f8d48a';ctx.beginPath();ctx.arc(7,-3,3,0,TAU);ctx.fill();ctx.fillStyle='#bc6342';ctx.beginPath();ctx.moveTo(-3,1);ctx.lineTo(-13,-5+Math.sin(t*9)*3);ctx.lineTo(-7,6);ctx.closePath();ctx.fill();ctx.restore()}
function draw(){ctx.setTransform(D,0,0,D,0,0);ctx.clearRect(0,0,W,H);ctx.save();if(shake>0)ctx.translate(rand(-shake,shake),rand(-shake,shake));drawGround();for(let o of orbs){let q=world(o.x,o.y);ctx.save();ctx.translate(q.x,q.y);ctx.shadowColor='#e9bc62';ctx.shadowBlur=13;ctx.fillStyle='#ffd88b';ctx.beginPath();ctx.arc(0,0,4+Math.sin(t*8+o.x)*1.2,0,TAU);ctx.fill();ctx.restore()}for(let e of foes)drawFoe(e);for(let b of shots){let q=world(b.x,b.y);ctx.save();ctx.translate(q.x,q.y);ctx.shadowColor=b.enemy?'#c86c59':'#f0a548';ctx.shadowBlur=15;ctx.fillStyle=b.enemy?'#d27860':'#f9bd63';ctx.beginPath();ctx.arc(0,0,b.enemy?6:5,0,TAU);ctx.fill();ctx.restore()}for(let f of fx){if(f.slash){let q=world(f.x,f.y);ctx.save();ctx.translate(q.x,q.y);ctx.rotate(f.a);ctx.globalAlpha=clamp(f.life/f.max,0,1);ctx.strokeStyle='#f5d38d';ctx.shadowColor='#e6a84e';ctx.shadowBlur=14;ctx.lineWidth=9;ctx.beginPath();ctx.arc(0,0,f.reach*.75,-.78,.78);ctx.stroke();ctx.restore()}else{let q=world(f.x,f.y);ctx.globalAlpha=clamp(f.life/f.max,0,1);ctx.fillStyle=f.color;ctx.beginPath();ctx.arc(q.x,q.y,f.size,0,TAU);ctx.fill();ctx.globalAlpha=1}}if(state!=='title'||t>0)drawKnight();else{ctx.save();ctx.translate(W*.72,H*.55);ctx.scale(2.4,2.4);ctx.translate(-W*.5,-H*.5);drawKnight();ctx.restore()}ctx.restore();if(state==='title'){ctx.save();ctx.globalAlpha=.13;ctx.fillStyle='#eab45f';for(let i=0;i<24;i++){let x=(i*173+t*14)%W,y=(i*97+Math.sin(t+i)*40+H*.15)%H;ctx.beginPath();ctx.arc(x,y,1+(i%3),0,TAU);ctx.fill()}ctx.restore()}}
function frame(now){let dt=Math.min((now-last)/1000,.05)||0;last=now;if(state==='title'){t+=dt}else update(dt);draw();requestAnimationFrame(frame)}
last=performance.now();requestAnimationFrame(frame);
})();

